  if (!sameObject(m.rules, want.rules, (x, y) => sameEach(x, y, (x, y) => sameArray(x, y, 2)))) return ".rules";
  if (!sameObject(m.labels, want.labels, (x, y) => (x === null || x === undefined || y === null || y === undefined ? x === y : Object.is(x, y)))) return ".labels";
  if (!sameMap(m.counts, want.counts, (x, y) => Object.is(x, y))) return ".counts";
  if (!sameMap(m.spotsAt, want.spotsAt, (x, y) => sameSpot(x, y) === null)) return ".spotsAt";
