  if (!sameObject(a.rules, b.rules, (x, y) => sameEach(x, y, (x, y) => sameArray(x, y, 2)))) return ".rules";
  if (!sameObject(a.labels, b.labels, (x, y) => (x === null || x === undefined || y === null || y === undefined ? x === y : Object.is(x, y)))) return ".labels";
  if (!sameMap(a.counts, b.counts, (x, y) => Object.is(x, y))) return ".counts";
  if (!sameMap(a.spotsAt, b.spotsAt, (x, y) => sameSpot(x, y) === null)) return ".spotsAt";
  if (!sameMap(a.tally, b.tally, (x, y) => Object.is(x, y))) return ".tally";
  if (!sameMap(a.queues, b.queues, (x, y) => sameEach(x, y, (x, y) => Object.is(x, y)))) return ".queues";
