  if (!Object.is(m.size, want.size)) return ".size";
  if (!Object.is(m.small, want.small)) return ".small";
  if (!Object.is(m.light, want.light)) return ".light";
  if (!Object.is(m.mass, want.mass)) return ".mass";
  if (!Object.is(m.on, want.on)) return ".on";
  if (!sameVec(m.where, want.where)) return ".where";
  if (!sameQuat(m.facing, want.facing)) return ".facing";
  if (!sameArray(m.pair, want.pair, 2)) return ".pair";
  if (!Object.is(m.name, want.name)) return ".name";
  if (!Object.is(m.colour, want.colour)) return ".colour";
  if (!Object.is(m.def, want.def)) return ".def";
  { const p = m.owner, q = want.owner; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".owner"; } else { if (!Object.is(p, q)) return ".owner"; } }
  if (!sameHolder(m.holder, want.holder)) return ".holder";
  { const p = m.spot, q = want.spot; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".spot"; } else { { const d = sameSpot(p, q); if (d) return ".spot" + d; } } }
  if (!sameList(m.friends && [...m.friends], want.friends && [...want.friends])) return ".friends";
  { const p = m.next, q = want.next; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".next"; } else { if (!Object.is(p, q)) return ".next"; } }
  { const p = m.tags, q = want.tags; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".tags"; } else { if (!sameMap(p, q, (x, y) => Object.is(x, y))) return ".tags"; } }
  if (!sameEach(m.marks, want.marks, (x, y) => Object.is(x, y))) return ".marks";
  if (!sameEach(m.probes, want.probes, (x, y) => sameVec(x, y))) return ".probes";
  if (!sameEach(m.flags, want.flags, (x, y) => Object.is(x, y))) return ".flags";
  if (!sameEach(m.spots, want.spots, (x, y) => sameSpot(x, y) === null)) return ".spots";
  if (!sameEach(m.holders, want.holders, (x, y) => sameHolder(x, y))) return ".holders";
