  if (!sameEach(m.maybe, want.maybe, (x, y) => (x === null || x === undefined || y === null || y === undefined ? x === y : Object.is(x, y)))) return ".maybe";
  if (!sameMap(m.seenBy, want.seenBy, (x, y) => Object.is(x, y))) return ".seenBy";
  if (!sameObject(m.marked, want.marked, (x, y) => (x === null || x === undefined || y === null || y === undefined ? x === y : sameSpot(x, y) === null))) return ".marked";
