export function sameThing(a, b) {
  if (!Object.is(a.count, b.count)) return ".count";
  if (!Object.is(a.size, b.size)) return ".size";
  if (!Object.is(a.small, b.small)) return ".small";
  if (!Object.is(a.light, b.light)) return ".light";
  if (!Object.is(a.mass, b.mass)) return ".mass";
  if (!Object.is(a.on, b.on)) return ".on";
  if (!sameVec(a.where, b.where)) return ".where";
  if (!sameQuat(a.facing, b.facing)) return ".facing";
  if (!sameArray(a.pair, b.pair, 2)) return ".pair";
  if (!Object.is(a.name, b.name)) return ".name";
  if (!Object.is(a.colour, b.colour)) return ".colour";
  if (!Object.is(a.def, b.def)) return ".def";
  { const p = a.owner, q = b.owner; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".owner"; } else { if (!Object.is(p, q)) return ".owner"; } }
  if (!sameHolder(a.holder, b.holder)) return ".holder";
  { const p = a.spot, q = b.spot; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".spot"; } else { { const d = sameSpot(p, q); if (d) return ".spot" + d; } } }
  if (!sameList(a.friends && [...a.friends], b.friends && [...b.friends])) return ".friends";
  { const p = a.next, q = b.next; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".next"; } else { if (!Object.is(p, q)) return ".next"; } }
  { const p = a.tags, q = b.tags; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".tags"; } else { if (!sameMap(p, q, (x, y) => Object.is(x, y))) return ".tags"; } }
  if (!Object.is(a.hidden, b.hidden)) return ".hidden";
  if (!Object.is(a.box?.size, b.box?.size)) return ".boxed";
  if (!sameEach(a.marks, b.marks, (x, y) => Object.is(x, y))) return ".marks";
  if (!sameEach(a.probes, b.probes, (x, y) => sameVec(x, y))) return ".probes";
  if (!sameEach(a.flags, b.flags, (x, y) => Object.is(x, y))) return ".flags";
  if (!sameEach(a.spots, b.spots, (x, y) => sameSpot(x, y) === null)) return ".spots";
  if (!sameEach(a.holders, b.holders, (x, y) => sameHolder(x, y))) return ".holders";
  if (!sameArray(a.matrix?.elements, b.matrix?.elements, 16)) return ".matrix";
  if (!Object.is(a.boxes?.[0]?.size, b.boxes?.[0]?.size)) return ".firstSize";
  if (!sameEach(a.shapes, b.shapes, (x, y) => sameShape(x, y) === null)) return ".shapes";
  { const x = a.hitSet, y = b.hitSet; if (x === null || x === undefined || y === null || y === undefined ? x !== y : (a.shapes ?? []).indexOf(x) !== (b.shapes ?? []).indexOf(y)) return ".hitSet"; }
  if (!sameBody(a.body, b.body)) return ".body";
  { const p = a.gains, q = b.gains; if (p === null || p === undefined || q === null || q === undefined) { if (p !== q) return ".gains"; } else { if (!sameTyped(p, q, 2)) return ".gains"; } }
  if (!sameEach(a.maybe, b.maybe, (x, y) => (x === null || x === undefined || y === null || y === undefined ? x === y : Object.is(x, y)))) return ".maybe";
  if (!sameMap(a.seenBy, b.seenBy, (x, y) => Object.is(x, y))) return ".seenBy";
  if (!sameObject(a.marked, b.marked, (x, y) => (x === null || x === undefined || y === null || y === undefined ? x === y : sameSpot(x, y) === null))) return ".marked";
  return null;
}

export function exportThing(o, cx) {
  let v = cx.seen.get(o);
  if (v) return v;
  v = {};
  cx.seen.set(o, v);
  v.$id = cx.ref("thing", o);
  v.count = o.count;
  v.size = o.size;
  v.small = o.small;
  v.light = o.light;
  v.mass = o.mass;
  v.on = o.on;
  v.where = o.where.clone();
  v.facing = o.facing.clone();
  v.pair = [...o.pair];
  v.name = o.name;
  v.colour = o.colour;
  v.def = cx.def("goods", o.def);
  v.owner = ((x) => (x === null || x === undefined ? x : cx.ref("person", x)))(o.owner);
  v.holder = exportHolder(o.holder, cx);
  v.spot = ((x) => (x === null || x === undefined ? x : exportSpot(x, cx)))(o.spot);
  v.friends = new Set([...o.friends].map((x) => cx.ref("person", x)));
  v.next = ((x) => (x === null || x === undefined ? x : cx.ref("thing", x)))(o.next);
  v.tags = ((x) => (x === null || x === undefined ? x : new Map(x)))(o.tags);
  v.hidden = o.hidden;
  v.boxed = o.box?.size;
  v.marks = o.marks.map((x) => x);
  v.probes = o.probes.map((x) => x.clone());
  v.flags = o.flags.map((x) => x);
  v.spots = o.spots.map((x) => exportSpot(x, cx));
  v.holders = o.holders.map((x) => exportHolder(x, cx));
  v.matrix = o.matrix.clone();
  v.firstSize = o.boxes?.[0]?.size;
  v.shapes = o.shapes.map((x) => exportShape(x, cx));
  v.hitSet = ((x) => (x === null || x === undefined ? x : exportShape(x, cx)))(o.hitSet);
  v.body = exportBody(o.body, cx);
  v.gains = ((x) => (x === null || x === undefined ? x : x.slice()))(o.gains);
  v.maybe = o.maybe.map((x) => x);
  v.seenBy = new Map([...o.seenBy].map(([k, x]) => [cx.ref("person", k), x]));
  v.marked = Object.fromEntries(Object.entries(o.marked).map(([k, x]) => [k, (x === null || x === undefined ? x : exportSpot(x, cx))]));
  return v;
}
